// NOT MY CODE
float sdf_box( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

//Gradient sampler from https://iquilezles.org/articles/palettes/
vec3 palette(float t) 
{
    const vec3 a = vec3(0.5, 0.5, 0.5);
    const vec3 b = vec3(0.5, 0.5, 0.5);
    const vec3 c = vec3(2.0, 1.0, 0.0);
    const vec3 d = vec3(0.50, 0.20, 0.25);
    return a + b * cos(6.28318 * (c * t + d));
}

//Function to create a 2D rotation matrix
mat2 rotate2D(float angle)
{
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}
// IS "MY" CODE
float sdf_sphere(vec3 point, float radius) {
    return length(point) - radius;
}

float sdf_scene(vec3 position) 
{

    float rad = 0.5;
    //position.y+= sin(position.z)*rad;
    //position.x+= cos(position.z)*rad;

    position.xy *= rotate2D(position.z)/10.0;
    //position = normalize(position);

    position = mod(position, vec3(1.0,1.0,1.0));
    position = position - vec3(0.5, 0.5, 0.5);
    float box = sdf_box(position, vec3(.125));
    //float sphere = sdf_sphere(position, 0.2);



    return box;
}

float ray_march(vec3 ray_origin, vec3 ray_direction) 
{
    float total_distance = 0.0;
    for(int i = 0 ; i < 1000 ; ++i) 
    {
        vec3 query_point = ray_origin + ray_direction * total_distance;

        float distance_to_scene = sdf_scene(query_point);
        if(distance_to_scene < 0.0001) break;
        total_distance += distance_to_scene;

        if(total_distance > 1000.0) break;
    }

    return total_distance;
}


vec3 get_color(vec3 origin, vec3 direction) {
    float t_dist = ray_march(origin, direction);
    vec3 point = origin + direction * t_dist;
    vec3 color = palette(length(point)/15.);
    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;
    uv -= vec2(0.5,0.5);
    float aspect = iResolution.x / iResolution.y;

    uv.x = uv.x * aspect;

    vec3 ray_origin = vec3(sin(iTime)*-0.2,cos(iTime)*0.1,iTime*10.);
    vec3 ray_direction = vec3(uv.x,uv.y, 1.);
    //ray_direction.xz*= rotate2D(cos(iTime)*0.2);
    //ray_direction.yz*= rotate2D(sin(iTime)*0.1);
    ray_direction = normalize(ray_direction);


    // RAY HAS ARRIVED
    float march_distance = ray_march(ray_origin, ray_direction);


    // Output to screen
    fragColor = vec4(get_color(ray_origin, ray_direction), 0.0);
}
